#!/usr/bin/env node
/**
 * Widens @capacitor-community/apple-sign-in's SwiftPM pin so it resolves
 * against Capacitor 8.
 *
 * THE CONFLICT
 * ios/App/CapApp-SPM/Package.swift (generated by the Capacitor CLI) pins
 * capacitor-swift-pm to `exact: "8.3.1"`, matching @capacitor/core 8.3.1.
 * The community plugin's own Package.swift declares `from: "7.0.0"`, which in
 * SwiftPM means 7.0.0..<8.0.0. The intersection is empty, so Xcode fails with
 * "Failed to resolve dependencies" and "Missing package product 'CapApp-SPM'".
 *
 * WHY WIDENING IS SAFE, AND WHY WE DON'T JUST UPGRADE THE PLUGIN
 * There is no 8.x of this plugin — 7.1.0 is the latest ever published, so
 * aligning versions is not an option. But the plugin's Swift source uses only
 * CAPPlugin, CAPPluginCall, CAPBridgedPlugin, CAPPluginMethod and
 * CAPPluginReturnPromise, none of which changed between capacitor-swift-pm 7
 * and 8. The pin is conservative, not a real incompatibility.
 *
 * The alternative was downgrading Capacitor to 7.x across the whole project,
 * which is a far larger change than this build is meant to contain.
 *
 * Runs on postinstall because npm install rewrites node_modules. Idempotent,
 * and a no-op if the plugin is absent, so CI without iOS deps still succeeds.
 *
 * POST-BETA: replace this with a vendored copy of the plugin, or drop the
 * community plugin for a first-party Sign in with Apple implementation.
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";

const MANIFEST = "node_modules/@capacitor-community/apple-sign-in/Package.swift";
const FROM = '.package(url: "https://github.com/ionic-team/capacitor-swift-pm.git", from: "7.0.0")';
const TO = '.package(url: "https://github.com/ionic-team/capacitor-swift-pm.git", "7.0.0"..<"9.0.0")';

if (!existsSync(MANIFEST)) {
  process.exit(0);
}

const src = readFileSync(MANIFEST, "utf8");

if (src.includes(TO)) {
  console.log("  apple-sign-in: SwiftPM range already widened");
  process.exit(0);
}

if (!src.includes(FROM)) {
  console.warn(
    "  apple-sign-in: expected pin not found — the plugin may have changed.\n" +
      "  Check its Package.swift against ios/App/CapApp-SPM/Package.swift before archiving."
  );
  process.exit(0);
}

writeFileSync(MANIFEST, src.replace(FROM, TO));
console.log('  apple-sign-in: capacitor-swift-pm pin widened to "7.0.0"..<"9.0.0"');
